//! Writes `guest-sdks/dotnet/native/isoplane_imports.h`, the C declaration of
//! each host import, from `imports::IMPORTS`. A `(ptr, len)` buffer is a
//! pointer and a length; any other parameter is named for its position.

#![forbid(unsafe_code)]

use std::error::Error;
use std::fmt::Write;

use isoplane_abi::imports::{BufSpec, Ty, HOST_MODULE, IMPORTS};

fn main() -> Result<(), Box<dyn Error>> {
    let mut text = String::from(
        "/* Generated by `task generate:abi` from isoplane_abi::imports::IMPORTS. */\n#include <stdint.h>\n",
    );
    for import in IMPORTS {
        let result = match import.sig.results {
            [] => "void",
            [ty] => scalar(*ty),
            _ => return Err(format!("{} returns more than one value", import.name).into()),
        };
        let (buffer, pointer) = match import.buf {
            BufSpec::None => (None, ""),
            BufSpec::In(index) => (Some(usize::from(index)), "const void *ptr"),
            BufSpec::Out(index) => (Some(usize::from(index)), "void *ptr"),
        };
        let parameters = import
            .sig
            .params
            .iter()
            .enumerate()
            .map(|(index, ty)| match buffer {
                Some(start) if index == start => pointer.to_owned(),
                Some(start) if index == start + 1 => "int32_t len".to_owned(),
                _ => format!("{} a{index}", scalar(*ty)),
            })
            .collect::<Vec<_>>();
        let parameters = if parameters.is_empty() {
            "void".to_owned()
        } else {
            parameters.join(", ")
        };
        writeln!(
            text,
            "__attribute__((import_module(\"{HOST_MODULE}\"), import_name(\"{name}\")))\n\
             extern {result} isoplane_{name}({parameters});",
            name = import.name
        )?;
    }
    std::fs::write(
        concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../guest-sdks/dotnet/native/isoplane_imports.h"
        ),
        text,
    )?;
    Ok(())
}

fn scalar(ty: Ty) -> &'static str {
    match ty {
        Ty::I32 => "int32_t",
        Ty::I64 => "int64_t",
    }
}
